268		if _, err := b.EffectiveVersionAt("seat", dtOldStart.Add(-time.Nanosecond)); !errors.Is(err, ErrNoEffectiveVersion) {
269			t.Fatalf("首版开始之前应返回 ErrNoEffectiveVersion, got %v", err)
270		}
271	}
272	
273	// 报价与查询共用同一套实际有效期判断：时钟停在 v2 的有效区间内时，
274	// 引用 v2 按 180 分确认，引用实际结束已提前到 3 月 10 日的 v1 则以
275	// version_expired 拒绝——即使 v1 的登记结束 3 月 31 日仍在将来。
276	func TestQuoteAfterSecondTruncation(t *testing.T) {
277		now, setNow := fixedClock(dtOldStart)
